import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import Login from './components/pages/Login';
import Register from './components/pages/Register';
import Products from './components/pages/Products';
import ProductDetail from './components/pages/ProductDetail';
import ProductForm from './components/pages/ProductForm';
import Users from './pages/Users';
import authService from './services/auth';

function App() {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        checkAuth();
    }, []);

    const checkAuth = async () => {
        if (authService.isAuthenticated()) {
            const userData = await authService.getCurrentUser();
            setUser(userData);
        }
        setLoading(false);
    };

    const handleLogout = async () => {
        await authService.logout();
        setUser(null);
    };

    const userRole = authService.getUserRole();
    const isAdmin = userRole === 'admin';
    const isSeller = userRole === 'seller';

    if (loading) {
        return <div className="text-center mt-5">Загрузка приложения...</div>;
    }

    return (
        <Router>
            <div className="App">
                <Navbar user={user} onLogout={handleLogout} />
                <div className="container mt-4">
                    <Routes>
                        <Route 
                            path="/login" 
                            element={user ? <Navigate to="/products" /> : <Login setUser={setUser} />} 
                        />
                        <Route 
                            path="/register" 
                            element={user ? <Navigate to="/products" /> : <Register />} 
                        />
                        <Route 
                            path="/products" 
                            element={user ? <Products /> : <Navigate to="/login" />} 
                        />
                        <Route 
                            path="/products/:id" 
                            element={user ? <ProductDetail /> : <Navigate to="/login" />} 
                        />
                        <Route 
                            path="/products/new" 
                            element={user && (isSeller || isAdmin) ? <ProductForm /> : <Navigate to="/products" />} 
                        />
                        <Route 
                            path="/products/:id/edit" 
                            element={user && (isSeller || isAdmin) ? <ProductForm /> : <Navigate to="/products" />} 
                        />
                        <Route 
                            path="/users" 
                            element={user && isAdmin ? <Users /> : <Navigate to="/products" />} 
                        />
                        <Route path="/" element={<Navigate to="/products" />} />
                    </Routes>
                </div>
            </div>
        </Router>
    );
}

export default App;
